@startuml

class Patient {
  + patientID : int
  + symptoms : string[]
  + doctor : Doctor
}

class Diagnosis {
  + diagnosisID : int
  + patient : Patient
  + doctor : Doctor
  + treatmentPlan : TreatmentPlan
  + consentGiven : boolean
  + priorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

abstract class Treatment {
  + treatmentID : int
  + diagnosis : Diagnosis
  + stage : int
  + consentRequired : boolean
}

class Stage1Treatment extends Treatment {}

class Stage2Treatment extends Treatment {}

class Stage3Treatment extends Treatment {}

class Doctor {
  + doctorID : int
  + name : string
  + approvedDiagnoses : Diagnosis[]
}

abstract class TreatmentPlan {
  + treatmentPlanID : int
  + advisedTreatments : Treatment[]
}

class HeadDoctor extends Doctor {}

class Nurse {
  + nurseID : int
  + name : string
  + patientFollowUpRate : int
}

Patient "1" -- "*" Diagnosis
Diagnosis "1" -- "0..*" Treatment
Treatment "1" -- "1" Diagnosis
HeadDoctor "1" -- "*" Diagnosis
Nurse "1" -- "*" Patient

@enduml

